import React from 'react';
import Data from '../Data.js';
import Navbar from '../components/Navbar.jsx';
import '../Gallery.css';

const Gallery = () => {
  // Aggregate all gallery images from Data, plus the main thumb
  const allImages = Data.reduce((acc, item) => {
    const mainImg = {
      src: item.img,
      title: item.title,
      location: item.location
    };

    const extraImgs = (item.gallery || []).map(url => ({
      src: url,
      title: item.title,
      location: item.location
    }));

    return [...acc, mainImg, ...extraImgs];
  }, []);

  return (
    <main className="gallery-page">
      <Navbar defaultSticky />

      <div className="gallery-header">
        <h1>Visual Journey</h1>
        <p>A collection of moments captured across the globe.</p>
      </div>

      <div className="masonry-grid">
        {allImages.map((img, idx) => (
          <div key={idx} className="masonry-item">
            <img src={img.src} alt={img.title} />
            <div className="masonry-overlay">
              <div className="masonry-info">
                <h4>{img.title}</h4>
                <p>{img.location}</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </main>
  );
};

export default Gallery;
